#include "KIniFile.h"   // Engine/Src/KIniFile.h (Core da link Engine.lib, KPlayer.h:101 da forward-declare KIniFile)
struct KIniEntry { KIniFile Ini; std::string strFile; int nRef; };
static std::map<std::string, KIniEntry*> s_mapIniFiles;   // khoa = tham so 2 (szName), giong Linux 0x978265C

static KIniEntry* sGetIniByName(Lua_State* L, int nArg)
{
    if (Lua_GetTopIndex(L) >= nArg && Lua_IsString(L, nArg)) {
        const char* szName = lua_tostring(L, nArg);
        if (szName && szName[0]) {
            std::map<std::string, KIniEntry*>::iterator it = s_mapIniFiles.find(szName);
            if (it != s_mapIniFiles.end()) return it->second;
        }
    }
    return NULL;
}

int LuaIniFile_Load(Lua_State* L)                // IniFile_Load(szFile, szName) -> 1/0
{
    if (Lua_GetTopIndex(L) < 2) { Lua_PushNumber(L, 0); return 1; }     // disasm: gettop<=1 -> push 0
    const char* szFile = lua_tostring(L, 1);
    const char* szName = lua_tostring(L, 2);
    if (!szFile || !szName || !szFile[0] || !szName[0]) { Lua_PushNumber(L, 0); return 1; }
    std::map<std::string, KIniEntry*>::iterator it = s_mapIniFiles.find(szName);
    if (it != s_mapIniFiles.end()) {             // da nap: cung ten tep -> ref++ tra 1; khac tep -> tra 0
        if (it->second->strFile != szFile) { Lua_PushNumber(L, 0); return 1; }
        it->second->nRef++; Lua_PushNumber(L, 1); return 1;
    }
    KIniEntry* p = new KIniEntry;                // chua co: nap moi
    if (!p->Ini.Load(szFile)) { delete p; Lua_PushNumber(L, 0); return 1; }   // KIniFile::Load KIniFile.h:48
    p->strFile = szFile; p->nRef = 1;
    s_mapIniFiles[szName] = p;
    Lua_PushNumber(L, 1); return 1;
}
