#include "KIniFile.h"
static std::map<std::string, KIniFile*> s_mapIniFiles;   // song suot doi tien trinh, giong s_mapTabFiles

static KIniFile* sGetIniFileByName(Lua_State* L, int nArg)
{
    if (Lua_GetTopIndex(L) >= nArg && Lua_IsString(L, nArg)) {
        const char* szName = lua_tostring(L, nArg);
        if (szName && szName[0]) {
            std::map<std::string, KIniFile*>::iterator it = s_mapIniFiles.find(szName);
            if (it != s_mapIniFiles.end()) return it->second;
        }
    }
    return NULL;   // Linux: khong co trong map -> tra ""
}

// IniFile_Load(szFile, szName) -> 0/1   (script luon goi Load(f, f))
int LuaIniFile_Load(Lua_State* L)
{
    if (Lua_GetTopIndex(L) < 1 || !Lua_IsString(L, 1)) { Lua_PushNumber(L, 0); return 1; }
    const char* szFile = lua_tostring(L, 1);
    const char* szName = (Lua_GetTopIndex(L) >= 2 && Lua_IsString(L, 2)) ? lua_tostring(L, 2) : szFile;
    KIniFile* pIni; std::map<std::string, KIniFile*>::iterator it = s_mapIniFiles.find(szName);
    if (it == s_mapIniFiles.end()) { pIni = new KIniFile; s_mapIniFiles[szName] = pIni; }
    else { pIni = it->second; pIni->Clear(); }
    Lua_PushNumber(L, pIni->Load(szFile) ? 1 : 0);   // KIniFile::Load  Engine\Src\KIniFile.h:48
    return 1;
}

// IniFile_GetData(szName, szSection, szKey) -> string ("" neu thieu)
int LuaIniFile_GetData(Lua_State* L)
{
    char szBuf[1024]; szBuf[0] = 0;                 // Linux: 0x400
    if (Lua_GetTopIndex(L) >= 3) {
        KIniFile* pIni = sGetIniFileByName(L, 1);
        if (pIni) {
            const char* szSect = lua_tostring(L, 2);
            const char* szKey  = lua_tostring(L, 3);
            pIni->GetString(szSect ? szSect : "", szKey ? szKey : "", "", szBuf, sizeof(szBuf)); // KIniFile.h:56
        }
    }
    Lua_PushString(L, szBuf);
    return 1;
}
