// KJx2WarInfra.cpp - (nMapId, szName) -> khong tra gi. Goc Linux: KSubWorldSet::SearchWorld + KSubWorld::ClearNpcWithName
int LuaClearMapNpcWithName(Lua_State* L)
{
	if (Lua_GetTopIndex(L) < 2 || !Lua_IsNumber(L, 1) || !Lua_IsString(L, 2))
		return 0;
	int nMapId = (int)Lua_ValueToNumber(L, 1);
	const char* szName = Lua_ValueToString(L, 2);
	if (!szName) return 0;
	int w = SubWorldSet.SearchWorld((DWORD)nMapId);   // KSubWorldSet.cpp:29 - instance DAU TIEN, giong goc
	if (w < 0) return 0;
	// (a) NPC dang song trong cac region - khuon LuaDelNpc ScriptFuns.cpp:6470-6474
	for (int r = 0; r < SubWorld[w].m_nTotalRegion; r++)
	{
		KIndexNode* pNode = (KIndexNode*)SubWorld[w].m_Region[r].m_NpcList.GetHead();
		while (pNode)
		{
			KIndexNode* pNext = (KIndexNode*)pNode->GetNext();   // lay next TRUOC khi xoa
			int i = pNode->m_nIndex;
			if (i > 0 && i < MAX_NPC && Npc[i].m_Kind != kind_player && Npc[i].m_Kind != kind_partner
				&& strcmp(Npc[i].Name, szName) == 0)
			{
				SubWorld[w].m_Region[r].RemoveNpc(i);
				SubWorld[w].m_Region[r].DecRef(Npc[i].m_MapX, Npc[i].m_MapY, obj_npc);
				NpcSet.Remove(i);
			}
			pNode = pNext;
		}
	}
	// (b) quai dang chet cho hoi sinh (KSubWorld.h:110) - goc cung xoa de khong hoi sinh lai
	KIndexNode* pNode = (KIndexNode*)SubWorld[w].m_NoneRegionNpcList.GetHead();
	while (pNode)
	{
		KIndexNode* pNext = (KIndexNode*)pNode->GetNext();
		int i = pNode->m_nIndex;
		if (i > 0 && i < MAX_NPC && Npc[i].m_Kind != kind_player && Npc[i].m_Kind != kind_partner
			&& strcmp(Npc[i].Name, szName) == 0)
		{
			Npc[i].m_Node.Remove();      // unlink khoi m_NoneRegionNpcList (goc: KList node Remove + m_Ref--)
			Npc[i].m_Node.DecRef();      // doi xung voi AddRef o KSubWorld.cpp:2278
			NpcSet.Remove(i);
		}
		pNode = pNext;
	}
	return 0;
}
