	int nTop = Lua_GetTopIndex(L);
	if (nTop != 3 && nTop != 7) return 0;          // giong ELF 0x0813136D
	int nPlayerIndex = GetPlayerIndex(L);
	if (nPlayerIndex <= 0) return 0;
	int nType = (int)Lua_ValueToNumber(L, 1);
