	int nIdx  = (int)Lua_ValueToNumber(L, 3);      // dong npcs.txt cua JX1 (PHAI remap tu id Linux)
	if (nType == 0) nTime = 0;
	else if (nType == 1) { if (nTime < 0) return 0; }
	else return 0;                                  // nType 2 (moc YYYYMMDDhhmm) khong call site nao trong tong -> bo
	KNpc* pNpc = &Npc[Player[nPlayerIndex].m_nIndex];
	if (nIdx >= 0)
	{
		Player[nPlayerIndex].m_ItemList.SetMaskLock(TRUE);   // KItemList.cpp:5188
		pNpc->m_MaskType = nIdx;                               // KNpc.h:425, sync qua PLAYER_NORMAL_SYNC (KNpc.cpp:5723)
		pNpc->m_nMaskTimeout = (nType == 1 && nTime > 0) ? g_SubWorldSet.GetGameTime() + nTime : 0; // TRUONG MOI
	}
	else
	{
		// nIdx = -1/-2: giu dang nguoi, doi 4 phan (helm/armor/weapon/horse) - JX1 khong khoa duoc, chi ghi tam
		if (nTop == 7)
		{
			pNpc->m_HelmType   = (int)Lua_ValueToNumber(L, 4);   // KNpc.h:417
			pNpc->m_ArmorType  = (int)Lua_ValueToNumber(L, 5);   // KNpc.h:418
			pNpc->m_WeaponType = (int)Lua_ValueToNumber(L, 6);   // KNpc.h:419
			int nHorse = (int)Lua_ValueToNumber(L, 7);           // KNpc.h:420-421
			pNpc->m_HorseType = nHorse < 0 ? 0 : nHorse; pNpc->m_bRideHorse = (nHorse >= 0);
		}
	}
	return 0;
}
