// TaskNo(szTaskName) -> TaskID | nil
int LuaTaskNo(Lua_State* L)
{
    if (Lua_GetTopIndex(L) != 1) return 0;            // disasm: gettop phai == 1
    const char* szName = lua_tostring(L, 1);
    if (!szName) return 0;
    std::map<std::string,int>::iterator it = s_mapTaskName2Id.find(szName);   // so sanh phan biet hoa/thuong nhu goc
